import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { mix, color, uv } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  const group = new Group();
  const timelines = [];

  // Colors
  const colors = {
    paper: '#e8ecf2',
    accent: '#ff2a38',
    gradientTop: '#1b1b23',
    gradientBottom: '#101015',
    inactive: '#a6adba'
  };

  // Dimensions
  const railWidth = 3.6;
  const railHeight = 0.5;
  const entryWidth = 0.6;
  const entryHeight = 0.34;
  const spacing = 0.68;
  const numEntries = 5;

  // Create rail background with vertical gradient
  const railGeom = new PlaneGeometry(railWidth, railHeight);
  const railMat = new MeshStandardNodeMaterial();
  const uvNode = uv();
  railMat.colorNode = mix(
    color(colors.gradientTop),
    color(colors.gradientBottom),
    uvNode.y
  );
  railMat.roughness = 0.55;
  railMat.metalness = 0.5;
  railMat.clearcoat = 0.2;
  railMat.anisotropy = 0.6;

  const railMesh = new Mesh(railGeom, railMat);
  railMesh.position.z = 0.15;
  group.add(railMesh);

  // Contact shadow plane
  const shadowGeom = new PlaneGeometry(railWidth + 0.4, railHeight * 0.5);
  const shadowMat = new MeshBasicNodeMaterial({
    color: 0x000000,
    opacity: 0.35,
    transparent: true
  });
  const shadowMesh = new Mesh(shadowGeom, shadowMat);
  shadowMesh.position.set(0, -0.06, 0.12);
  group.add(shadowMesh);

  // Entry definitions
  const entries = [
    { label: 'HOME', active: true, target: 'hub-home' },
    { label: 'FEATURES', active: false, target: 'hub-features' },
    { label: 'COLLECTION', active: false, target: 'hub-collection' },
    { label: 'PRICING', active: false, target: 'hub-pricing' },
    { label: 'JOURNAL', active: false, target: 'hub-journal' }
  ];

  const entryMeshes = [];
  const totalWidth = (numEntries - 1) * spacing;
  const startX = -totalWidth / 2;
  let activeEntryGroup = null;

  // Create entry groups
  entries.forEach((entry, idx) => {
    const posX = startX + idx * spacing;

    const entryGroup = new Group();
    entryGroup.position.set(posX, 0, 0);
    entryGroup.userData.target = entry.target;
    entryGroup.userData.isActive = entry.active;
    entryGroup.userData.index = idx;

    // Invisible hit mesh for interaction
    const hitGeom = new PlaneGeometry(entryWidth, entryHeight);
    const hitMat = new MeshBasicNodeMaterial({ transparent: true, opacity: 0 });
    const hitMesh = new Mesh(hitGeom, hitMat);
    entryGroup.add(hitMesh);
    entryGroup.userData.hitMesh = hitMesh;

    // Text label
    const textColor = entry.active ? colors.paper : colors.inactive;
    const textObj = ctx.fontAtlas.createText(entry.label, {
      fontSize: 13,
      color: textColor,
      align: 'center',
      letterSpacingPx: 1.04
    });
    textObj.position.z = 0.05;
    entryGroup.add(textObj);
    entryGroup.userData.textObj = textObj;

    if (entry.active) {
      activeEntryGroup = entryGroup;
    }

    group.add(entryGroup);
    entryMeshes.push(entryGroup);
  });

  // Single underline positioned at active entry
  const underlineGeom = new PlaneGeometry(0.28, 0.025);
  const underlineMat = new MeshBasicNodeMaterial({
    color: colors.accent,
    emissive: colors.accent,
    emissiveIntensity: 1.8
  });
  const underlineMesh = new Mesh(underlineGeom, underlineMat);
  underlineMesh.position.set(startX, -0.15, 0.06);
  group.add(underlineMesh);
  group.userData.underline = underlineMesh;

  // Helper: extract text material
  const getTextMaterial = (textObj) => {
    if (textObj.material) return textObj.material;
    if (textObj.children && textObj.children.length > 0) {
      return textObj.children[0].material || null;
    }
    return null;
  };

  // Helper: hex to RGB
  const hexToRgb = (hex) => {
    const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
    return result ? {
      r: parseInt(result[1], 16) / 255,
      g: parseInt(result[2], 16) / 255,
      b: parseInt(result[3], 16) / 255
    } : { r: 1, g: 1, b: 1 };
  };

  const inactiveRgb = hexToRgb(colors.inactive);
  const activeRgb = { r: 1, g: 1, b: 1 };

  // Event handlers
  group.userData.handlers = {
    click: (event) => {
      const targetMesh = event.object;
      const targetGroup = entryMeshes.find(e => e.userData.hitMesh === targetMesh);

      if (!targetGroup) return;

      // Switch active entry
      if (activeEntryGroup !== targetGroup) {
        // Transition old active entry
        if (activeEntryGroup) {
          const oldMat = getTextMaterial(activeEntryGroup.userData.textObj);
          if (oldMat && oldMat.color) {
            gsap.to(oldMat.color, {
              ...inactiveRgb,
              duration: 0.26,
              ease: 'back.out(1.04)'
            });
          }
          activeEntryGroup.userData.isActive = false;
        }

        // Transition new active entry
        const newMat = getTextMaterial(targetGroup.userData.textObj);
        if (newMat && newMat.color) {
          gsap.to(newMat.color, {
            ...activeRgb,
            duration: 0.26,
            ease: 'back.out(1.04)'
          });
        }
        targetGroup.userData.isActive = true;

        // Animate underline to new entry
        const underlineTl = gsap.timeline();
        underlineTl.to(group.userData.underline.position, {
          x: targetGroup.position.x,
          duration: 0.26,
          ease: 'back.out(1.04)'
        });
        timelines.push(underlineTl);

        ctx.emit('navigate', { to: targetGroup.userData.target });
        activeEntryGroup = targetGroup;
      }

      // Press animation
      const pressTl = gsap.timeline();
      pressTl.to(targetGroup.scale, {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'back.out'
      }, 0);
      pressTl.to(targetGroup.position, {
        z: -0.03,
        duration: 0.12,
        ease: 'back.out'
      }, 0);

      pressTl.to(targetGroup.scale, {
        x: 1,
        y: 1,
        duration: 0.2,
        ease: 'back.out'
      }, 0.12);
      pressTl.to(targetGroup.position, {
        z: 0,
        duration: 0.2,
        ease: 'back.out'
      }, 0.12);

      timelines.push(pressTl);
    },

    mouseenter: (event) => {
      const targetMesh = event.object;
      const targetGroup = entryMeshes.find(e => e.userData.hitMesh === targetMesh);

      if (!targetGroup || targetGroup.userData.isActive) return;

      const textMat = getTextMaterial(targetGroup.userData.textObj);
      if (textMat && textMat.color) {
        gsap.to(textMat.color, {
          r: 1,
          g: 1,
          b: 1,
          duration: 0.16
        });
      }
    },

    mouseleave: (event) => {
      const targetMesh = event.object;
      const targetGroup = entryMeshes.find(e => e.userData.hitMesh === targetMesh);

      if (!targetGroup || targetGroup.userData.isActive) return;

      const textMat = getTextMaterial(targetGroup.userData.textObj);
      if (textMat && textMat.color) {
        gsap.to(textMat.color, {
          ...inactiveRgb,
          duration: 0.16
        });
      }
    }
  };

  // Mount animation
  const mountTl = gsap.timeline();
  group.position.y = 0.4;
  mountTl.to(group.position, {
    y: 0,
    duration: 0.7,
    ease: 'power3.out'
  });
  timelines.push(mountTl);

  // Cleanup
  group.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());

    railGeom.dispose();
    railMat.dispose();
    shadowGeom.dispose();
    shadowMat.dispose();
    underlineGeom.dispose();
    underlineMat.dispose();

    entryMeshes.forEach(entry => {
      if (entry.userData.hitMesh) {
        entry.userData.hitMesh.geometry.dispose();
        entry.userData.hitMesh.material.dispose();
      }
    });
  };

  return group;
}
